export const fields={plan:'适用品牌计划',status:'开启状态',coverage:'核对覆盖',plan_key:'计划行编号',product:'产品 / 型号',market:'市场',language:'语言',body:'正文',headline:'标题',description:'描述',asset:'素材文件名 / 来源',url:'产品或活动页',offer:'批准优惠金额 / 比例',currency:'币种 / 优惠单位',condition:'优惠条件',start:'生效日',end:'结束日',campaign:'Campaign 名称包含',ad_name:'广告名称',adset:'广告组名称',campaign_name:'所属 Campaign',campaign_status:'Campaign 状态',adset_status:'Ad Set 状态',ad_status:'Ad 状态',asset_hash:'实际原文件 SHA256',image_offer:'图片压字优惠（已取证）',page_product:'页面产品 / 型号',page_market:'页面适用市场',image_currency:'图片优惠单位',image_condition:'图片优惠条件',page_offer:'页面产品优惠（已取证）',page_currency:'页面币种 / 单位',page_condition:'页面优惠条件',evidence:'取证出处',captured_at:'取证时间'};
export const planFields=['plan_key','product','market','language','body','headline','description','asset','url','offer','currency','condition','start','end','campaign'];
export const actualFields=['plan_key','product','market','language','ad_name','campaign_name','adset','body','headline','description','asset_hash','campaign_status','adset_status','ad_status','image_offer','image_currency','image_condition','page_product','page_market','page_offer','page_currency','page_condition','evidence','captured_at'];
const aliases={plan_key:['计划行编号','plan_key','素材编号'],product:['产品','产品名称','product','sku','型号'],market:['市场','market','country','国家'],language:['language','语言'],body:['正文','文案','primary text','ad body','body'],headline:['标题','headline','ad title'],description:['描述','description','description asset text'],asset:['素材','素材链接','图片','asset','素材文件名 / 来源'],url:['落地页','url','landing page'],offer:['优惠','折扣','offer'],currency:['币种','currency'],condition:['优惠条件','condition'],start:['开始日期','生效日','start'],end:['结束日期','end'],campaign:['campaign','campaign 名称包含']};
export function mappingFor(headers,kind){return Object.fromEntries((kind==='plan'?planFields:actualFields).map(k=>[k,headers.findIndex(h=>[fields[k],k,...aliases[k]||[]].some(a=>String(a).toLowerCase()===String(h).trim().toLowerCase()))]));}
export function rowsFrom(sheet,map,headerIndex,source,assets=[],kind='plan'){return sheet.rows.slice(headerIndex+1).map(r=>{const x={source:`${source.name} / ${sheet.name} / 第 ${r.row} 行`,source_hash:source.sha256,row:r.row,sheet:sheet.name,source_name:source.name};for(const [key,index] of Object.entries(map))if(Number(index)>=0)x[key]=String(r.cells[Number(index)]??'');if(kind==='plan')x.plan_key=x.plan_key||`${sheet.name}:${r.row}`;x.assets=assets.filter(a=>(a.source_hash===source.sha256&&a.anchor?.sheet===sheet.name&&a.anchor?.row===r.row)||((x.asset||'').split(/[;；\n]/).includes(a.name)));return x;}).filter(r=>Object.keys(map).some(k=>r[k]));}
export const norm=x=>String(x??'').normalize('NFC').replace(/\s+/g,' ').trim();
export function activePlanRows(version,date){return version.rows.filter(r=>(!r.start||r.start<=date)&&(!r.end||r.end>=date));}
export function validatePlan(rows){const errs=[];if(!rows.length)errs.push('没有数据行');const keys=new Set();for(const r of rows){if(keys.has(r.plan_key))errs.push(`计划行编号重复：${r.plan_key}`);keys.add(r.plan_key);if(!r.product||!r.market||!r.language)errs.push(`${r.source}：缺少产品、市场或语言，不能确定适用范围`);for(const k of ['start','end'])if(r[k]&&(!/^\d{4}-\d{2}-\d{2}$/.test(r[k])||isNaN(Date.parse(r[k]))))errs.push(`${r.source}：日期请用 YYYY-MM-DD`);if(r.start&&r.end&&r.start>r.end)errs.push(`${r.source}：结束日早于生效日`);}return [...new Set(errs)];}
export function audit(version,actual,date){const rows=activePlanRows(version,date),results=[];let excluded=0;const push=(category,field,p,a,expected,observed,reason)=>results.push({category,field,plan_key:p?.plan_key||a.plan_key||'',source:p?.source||'',expected:String(expected??''),observed:String(observed??''),reason,ad_name:a.ad_name||'(未提供广告名称)',campaign:a.campaign_name||'',adset:a.adset||'',evidence:a.evidence||'',captured_at:a.captured_at||''});
for(const a of actual){const statuses=['campaign_status','adset_status','ad_status'].map(k=>String(a[k]||'').toUpperCase());if(statuses.some(x=>['PAUSED','ARCHIVED','DELETED'].includes(x))){excluded++;continue;}if(statuses.some(x=>x!=='ACTIVE')){push('UNCHECKABLE','status',null,a,'三级均开启',statuses.join(' / '),'开启状态不完整，未参与执行检查');continue;}
const candidates=rows.filter(p=>(!a.plan_key||p.plan_key===a.plan_key)&&norm(p.product)===norm(a.product)&&norm(p.market)===norm(a.market)&&norm(p.language)===norm(a.language)&&(!p.campaign||norm(a.campaign_name).toLowerCase().includes(norm(p.campaign).toLowerCase())));
if(candidates.length!==1){push('MISSING_BASIS','plan',null,a,'唯一适用的品牌计划',candidates.length+' 个候选',candidates.length?'多条计划同时适用，需要明确计划行或范围':'没有适用的计划，或产品/市场/语言/有效期不匹配');continue;}
const p=candidates[0];let compared=0;
for(const k of ['body','headline','description']){if(!(k in p))continue;if(String(p[k]).includes('[公式未计算]')){push('UNCHECKABLE',k,p,a,p[k],a[k],'品牌表格公式未读取为结果');continue;}if(!(k in a)){push('UNCHECKABLE',k,p,a,p[k],'检查不到','实际广告未提供此字段');continue;}compared++;if(norm(p[k])!==norm(a[k]))push('EXECUTION_DIFFERENCE',k,p,a,p[k],a[k],'实际原文与品牌计划不同；不据翻译改写标准');}
const hashes=(p.assets||[]).map(x=>x.sha256);if(hashes.length&&a.asset_hash&&hashes.includes(a.asset_hash)){compared++;}else push('UNCHECKABLE','asset',p,a,(p.assets||[]).map(x=>x.name).join('、')||p.asset||'未提供原图',a.asset_hash?'文件不同，需核验视觉内容':'检查不到原图','仅原文件摘要相同可直接核对；不同摘要不等于上错图。下载链接、截图和目录尚不足以判断');
// Numeric checks only use explicitly supplied evidence, never unverified OCR or whole-page maxima.
if(p.offer){if(a.image_offer&&a.evidence&&a.captured_at&&p.currency&&norm(a.image_currency)===norm(p.currency)&&('condition'in p)&&('image_condition'in a)&&norm(a.image_condition)===norm(p.condition)){compared++;if(norm(p.offer)!==norm(a.image_offer))push('CONTENT_CONFLICT','image_offer',p,a,p.offer+' '+p.currency,a.image_offer+' '+a.image_currency,'图片压字与品牌优惠字段不同；需品牌确认正确值，暂不归责投手');}else push('UNCHECKABLE','image_offer',p,a,p.offer,'未提供已取证压字','本版不运行 OCR，需导入核实后的文字、单位、条件及取证出处/时间');
if(a.page_offer&&a.evidence&&a.captured_at&&norm(a.page_product)===norm(p.product)&&norm(a.page_market)===norm(p.market)&&p.currency&&a.page_currency&&norm(p.currency)===norm(a.page_currency)&&('condition'in p)&&('page_condition'in a)&&norm(p.condition)===norm(a.page_condition)&&a.captured_at.slice(0,10)===date){compared++;if(norm(p.offer)!==norm(a.page_offer))push('PAGE_OFFER_DIFFERENCE','page_offer',p,a,p.offer+' '+p.currency,a.page_offer+' '+a.page_currency,'已指定同一产品/市场来源；优惠与品牌标准不同，核对页面更新');}else push('UNCHECKABLE','page_offer',p,a,p.offer,a.page_offer||'检查不到','页面产品、币种、条件或当日取证不完整，不用全页最大优惠代替产品优惠');}
if(!compared)push('UNCHECKABLE','coverage',p,a,'可核对字段','无','本条没有完成可比字段核对');
}
const groups=new Map();for(const r of results){const key=JSON.stringify([version.id,r.category,r.plan_key,r.field,r.expected,r.observed,r.reason]);if(!groups.has(key))groups.set(key,{...r,key,ads:[]});groups.get(key).ads.push({name:r.ad_name,campaign:r.campaign,adset:r.adset});}
return {groups:[...groups.values()],excluded,checked:actual.length-excluded,date,version:version.id};}
export const categories={EXECUTION_DIFFERENCE:'执行偏差',CONTENT_CONFLICT:'内容冲突 · 需品牌确认',PAGE_OFFER_DIFFERENCE:'页面优惠不同步',MISSING_BASIS:'缺少执行依据',UNCHECKABLE:'检查不到'};
export const empty=()=>({schema:1,project:'demo',account:'demo-DE',demo:false,documents:[],versions:[],activeVersion:null,actual:[],feedback:{},events:[],sources:[]});
export function demo(){const s=empty();s.demo=true;const asset={name:'E1-DE-示例原图.svg',sha256:'demo-original-e1',preview:'demo-creative.svg'};const p={plan_key:'DE-E1-01',product:'E1 主机',market:'DE',language:'de',body:'Spare 100 € auf den E1.',headline:'E1 Angebot',description:'',asset:asset.name,assets:[asset],url:'https://example.com/eu-de/black-friday-sale',offer:'100',currency:'EUR',condition:'无需优惠码',start:'2026-11-01',end:'2026-11-30',campaign:'DE_E1',source:'虚构 Media Plan.xlsx / DE / 第 12 行'};
s.versions=[{id:'演示 v1',label:'品牌黑五计划 · 虚构示例',created_at:new Date().toISOString(),rows:[p],source:'虚构 Media Plan.xlsx'}];s.activeVersion='演示 v1';const a={...p,assets:undefined,ad_name:'E1_DE_常规01',campaign_name:'DE_E1_BF_TEST',adset:'Broad_DE',campaign_status:'ACTIVE',adset_status:'ACTIVE',ad_status:'ACTIVE',asset_hash:'demo-original-e1',image_offer:'100',image_currency:'EUR',image_condition:'无需优惠码',page_product:'E1 主机',page_market:'DE',page_offer:'100',page_currency:'EUR',page_condition:'无需优惠码',evidence:'预设虚构证据，不是实时抓取',captured_at:'2026-11-05T09:00:00+08:00'};
s.actual=[a,{...a,ad_name:'E1_DE_文案变更02',body:'Spare 150 € auf den E1.'},{...a,ad_name:'E1_DE_文案变更03',body:'Spare 150 € auf den E1.'},{...a,ad_name:'E1_DE_压字冲突04',image_offer:'150'},{...a,ad_name:'E1_DE_页面变化05',page_offer:'80'},{...a,ad_name:'E1_DE_新品06',product:'E1 套装',plan_key:''},{...a,ad_name:'E1_DE_图片缺口07',asset_hash:''},{...a,ad_name:'E1_DE_暂停08',ad_status:'PAUSED'}];return s;}
